css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .8); position: relative; }
.loader i { position: absolute; width: 6%; height: 6%; border-radius: 50%; background: var(--accent-2); animation: scope-twinkle calc(var(--loader-speed) * 1.8) ease-in-out infinite; }
.loader i:nth-of-type(1) { left: 12%; top: 10%; }
.loader i:nth-of-type(2) { left: 46%; top: 4%; animation-delay: calc(var(--loader-speed) * .45); }
.loader i:nth-of-type(3) { left: 74%; top: 14%; animation-delay: calc(var(--loader-speed) * .9); }
.loader i:nth-of-type(4) { left: 88%; top: 34%; animation-delay: calc(var(--loader-speed) * 1.35); }
.loader .tube { position: absolute; left: 26%; bottom: 30%; width: 52%; height: 15%; border-radius: 8px; background: linear-gradient(color-mix(in srgb, #fff 22%, var(--accent)), var(--accent)); transform-origin: 24% 60%; animation: scope-aim calc(var(--loader-speed) * 3.2) ease-in-out infinite; }
.loader .tube::after { content: ''; position: absolute; right: -8%; top: -20%; width: 18%; height: 140%; border-radius: 4px; background: var(--accent-2); }
.loader .legs { position: absolute; left: 28%; bottom: 6%; width: 26%; height: 30%; border-left: 4px solid #64748b; border-right: 4px solid #64748b; border-radius: 0 0 3px 3px; }
@keyframes scope-aim { 0%, 100% { transform: rotate(-8deg); } 45%, 62% { transform: rotate(-34deg); } }
@keyframes scope-twinkle { 0%, 100% { opacity: .25; transform: scale(.7); } 50% { opacity: 1; transform: scale(1.15); } }
